command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$candidate="3fdf27d12ddceff8c06c4f6195c621efcceea418"
$baseline="e9d6f485e992cf7532fb3928e301e38302aeceb6"
$temp=Join-Path $env:RUNNER_TEMP ("flyexplorer-docs-check-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main work/docs-current-state-20261005 --no-tags
  if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
  $resolved=(& git rev-parse refs/remotes/origin/work/docs-current-state-20261005).Trim()
  if($LASTEXITCODE -ne 0 -or $resolved -ne $candidate){throw "candidate ref mismatch: $resolved"}

  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp

  & git diff --check $baseline $candidate
  if($LASTEXITCODE -ne 0){throw "git diff --check failed"}

  & cmd /c test.bat policy
  if($LASTEXITCODE -ne 0){throw "policy validation failed"}

  & python -X utf8 -m unittest tests/winui/test_remote_windows_task_contract.py
  if($LASTEXITCODE -ne 0){throw "remote workflow contract failed"}

  $readme=Get-Content -Raw -Encoding UTF8 -LiteralPath "README"
  if($readme.Contains("main pushes automatically run the normal Release + GUI validation")){throw "stale README CI wording remains"}

  $project=Get-Content -Raw -Encoding UTF8 -LiteralPath ".agent-policy\PROJECT.md"
  foreach($stale in @(
    "bounded 6,000-entry isolated helper ceiling",
    "The tracked installer/provenance snapshot predates v7",
    '["none"] requires `configuration: "none"`'
  )){
    if($project.Contains($stale)){throw "stale PROJECT wording remains: $stale"}
  }

  $licenseReadme=Get-Content -Raw -Encoding UTF8 -LiteralPath "packaging\licenses\README.md"
  if($licenseReadme.Contains("2026-10-01 packaged runtime")){throw "stale provenance date remains"}

  Write-Host "DOCS_CURRENT_STATE_VALIDATION=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
